#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Suit {
    Hearts,
    Spades,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Status {
    Active,
    InReview,
    Done,
}

pub fn color(s: Suit) -> String {
    if s == Suit::Hearts {
        return String::from("red\n");
    }
    return String::from("black\n");
}

pub fn advance(s: Status) -> Status {
    if s == Status::Active {
        return Status::InReview;
    }
    return Status::Done;
}

pub fn label(s: Option<Status>) -> String {
    let Some(s) = s else {
        return String::from("none\n");
    };
    if s != Status::Done {
        return String::from("open\n");
    }
    return String::from("closed\n");
}

pub fn reds(suits: &[Suit]) -> i64 {
    let mut count: i64 = 0;
    for &s in suits {
        if s == Suit::Hearts {
            count += 1;
        }
    }
    return count;
}

fn main() {
    let s = Suit::Spades;
    print!("{}", color(s));
    print!("{}", color(Suit::Hearts));
    print!("{}", label(Some(advance(Status::Active))));
    print!("{}", label(Some(advance(Status::InReview))));
    print!("{}", label(None));
    print!("{}", reds(&[Suit::Hearts, s, Suit::Hearts]));
    print!("\n");
    let t = s;
    if t == Suit::Spades {
        print!("same\n");
    }
}
